// pages/dashboard/dashboard.js
const app = getApp()

Page({
  data: {
    sensorData: {
      temperature: 25,
      humidity: 60,
      light: 500,
      noise: 30
    },
    deviceStatus: {
      online: 0,
      offline: 0,
      total: 0
    },
    alerts: [],
    history: []
  },

  onLoad() {
    this.loadSensorData()
    this.loadDeviceStatus()
    this.loadAlerts()
  },

  onShow() {
    this.refreshData()
  },

  loadSensorData() {
    wx.request({
      url: `${app.globalData.serverUrl}/api/sensor`,
      success: (res) => {
        if (res.statusCode === 200) {
          this.setData({
            sensorData: res.data
          })
        }
      }
    })
  },

  loadDeviceStatus() {
    const devices = wx.getStorageSync('devices') || []
    const online = devices.filter(d => d.status === 'online').length
    this.setData({
      deviceStatus: {
        online: online,
        offline: devices.length - online,
        total: devices.length
      }
    })
  },

  loadAlerts() {
    wx.request({
      url: `${app.globalData.serverUrl}/api/alerts`,
      success: (res) => {
        if (res.statusCode === 200) {
          this.setData({
            alerts: res.data
          })
        }
      }
    })
  },

  refreshData() {
    this.loadSensorData()
    this.loadDeviceStatus()
    this.loadAlerts()
  },

  onPullDownRefresh() {
    this.refreshData()
    wx.stopPullDownRefresh()
  },

  goToDevices() {
    wx.switchTab({
      url: '/pages/devices/devices'
    })
  },

  dismissAlert(e) {
    const alertId = e.currentTarget.dataset.id
    wx.request({
      url: `${app.globalData.serverUrl}/api/alerts/${alertId}`,
      method: 'DELETE',
      success: () => {
        this.loadAlerts()
      }
    })
  }
})

