// pages/index/index.js
const app = getApp()

Page({
  data: {
    devices: [],
    status: '离线',
    temperature: '--',
    humidity: '--',
    lastUpdate: '--'
  },

  onLoad() {
    this.loadDevices()
    this.checkConnection()
  },

  onShow() {
    this.loadDevices()
  },

  loadDevices() {
    const devices = wx.getStorageSync('devices') || []
    const onlineCount = devices.filter(d => d.status === 'online').length
    this.setData({
      devices: devices,
      onlineCount: onlineCount,
      totalCount: devices.length
    })
  },

  checkConnection() {
    // 检查与 HomeMind 设备的连接
    wx.request({
      url: `${app.globalData.serverUrl}/api/status`,
      success: (res) => {
        if (res.statusCode === 200) {
          this.setData({
            status: '在线',
            temperature: res.data.temperature || '--',
            humidity: res.data.humidity || '--',
            lastUpdate: this.formatTime(new Date())
          })
        }
      },
      fail: () => {
        this.setData({
          status: '离线'
        })
      }
    })
  },

  formatTime(date) {
    const hour = date.getHours()
    const minute = date.getMinutes()
    return `${hour}:${minute < 10 ? '0' : ''}${minute}`
  },

  goToDashboard() {
    wx.switchTab({
      url: '/pages/dashboard/dashboard'
    })
  },

  goToDevices() {
    wx.switchTab({
      url: '/pages/devices/devices'
    })
  },

  goToCalendar() {
    wx.switchTab({
      url: '/pages/calendar/calendar'
    })
  },

  onPullDownRefresh() {
    this.checkConnection()
    wx.stopPullDownRefresh()
  }
})

// pages/devices/devices.js —— C1：对接真实后端（登录/绑定/下发/WS 回显）
const app = getApp()
const api = require('../../utils/api.js')
const ws = require('../../utils/ws.js')

Page({
  data: {
    devices: [],
    loading: false,
    pending: {},            // device_id -> command_id（执行中防重入）
    showAddModal: false,
    newDevice: { device_id: '', name: '' }
  },

  onShow() {
    this.ensureAndLoad()
  },

  onHide() {
    this.closeWs()
  },

  async ensureAndLoad() {
    try {
      await api.login()
      await this.loadDevices()
      this.openWs()
    } catch (e) {
      wx.showToast({ title: '登录/加载失败: ' + e.message, icon: 'none' })
    }
  },

  async loadDevices() {
    this.setData({ loading: true })
    try {
      const res = await api.getDevices()
      if (res.statusCode === 200) {
        const list = (res.data.devices || []).map((d) => ({
          id: d.device_id,
          name: d.name || d.device_id,
          online: d.online,
          led_state: d.led_state || 'unknown',
          last_seen: d.last_seen
        }))
        this.setData({ devices: list })
      }
    } catch (e) {
      console.error(e)
    } finally {
      this.setData({ loading: false })
    }
  },

  openWs() {
    this.closeWs()
    this._ws = ws.connect((msg) => this.onWsMessage(msg))
  },

  closeWs() {
    if (this._ws) {
      try { this._ws.close() } catch (e) {}
      this._ws = null
    }
  },

  onWsMessage(msg) {
    if (msg.type === 'snapshot') {
      if (this.data.devices.length === 0 && msg.devices) this.applyDevices(msg.devices)
    } else if (msg.type === 'status') {
      this.updateDevice(msg.device_id, { online: msg.online, led_state: msg.led })
    } else if (msg.type === 'command') {
      const pending = this.data.pending
      if (pending[msg.device_id] === msg.command_id) {
        const np = Object.assign({}, pending)
        delete np[msg.device_id]
        this.setData({ pending: np })
      }
      if (msg.status === 'expired') {
        wx.showToast({ title: '命令超时未执行', icon: 'none' })
        this.updateDevice(msg.device_id, { led_state: 'unknown' })
      }
    }
  },

  applyDevices(list) {
    const devices = list.map((d) => ({
      id: d.device_id,
      name: d.name || d.device_id,
      online: d.online,
      led_state: d.led_state || 'unknown'
    }))
    this.setData({ devices })
  },

  updateDevice(deviceId, patch) {
    const devices = this.data.devices.map((d) =>
      d.id === deviceId ? Object.assign({}, d, patch) : d)
    this.setData({ devices })
  },

  toggleDevice(e) {
    const deviceId = e.currentTarget.dataset.id
    const dev = this.data.devices.find((d) => d.id === deviceId)
    if (!dev || this.data.pending[deviceId]) return
    const action = dev.led_state === 'on' ? 'led.off' : 'led.on'
    api.sendCommand(deviceId, action, {}).then((res) => {
      if (res.statusCode === 200) {
        const pending = Object.assign({}, this.data.pending)
        pending[deviceId] = res.data.command_id
        this.setData({ pending })
        this.updateDevice(deviceId, { led_state: 'pending' })
      } else {
        wx.showToast({ title: '下发失败', icon: 'none' })
      }
    }).catch((err) => {
      wx.showToast({ title: '下发失败: ' + err.message, icon: 'none' })
    })
  },

  addDevice() {
    this.setData({ showAddModal: true, newDevice: { device_id: '', name: '' } })
  },
  hideAddModal() {
    this.setData({ showAddModal: false })
  },
  onInputChange(e) {
    const field = e.currentTarget.dataset.field
    this.setData({ ['newDevice.' + field]: e.detail.value })
  },
  async confirmAdd() {
    const self = this
    const dev = this.data.newDevice
    if (!dev.device_id) {
      wx.showToast({ title: '请输入设备ID', icon: 'none' })
      return
    }
    try {
      await api.login()
      const res = await api.request('POST', '/v1/devices', {
        device_id: dev.device_id, name: dev.name
      })
      if (res.statusCode === 200) {
        this.setData({ showAddModal: false })
        await this.loadDevices()
      } else {
        wx.showToast({ title: '绑定失败', icon: 'none' })
      }
    } catch (e) {
      wx.showToast({ title: '绑定失败: ' + e.message, icon: 'none' })
    }
  },

  deleteDevice(e) {
    const deviceId = e.currentTarget.dataset.id
    const self = this
    wx.showModal({
      title: '提示',
      content: '云端解绑接口本期未开放，仅从本机视图移除？',
      success: (r) => {
        if (r.confirm) {
          const devices = self.data.devices.filter((d) => d.id !== deviceId)
          self.setData({ devices })
        }
      }
    })
  },

  onPullDownRefresh() {
    this.loadDevices().then(() => wx.stopPullDownRefresh())
  }
})

// pages/calendar/calendar.js
const app = getApp()

Page({
  data: {
    calendarList: [],
    currentDate: '',
    selectedDate: '',
    showAddModal: false,
    newCalendar: {
      title: '',
      time: '',
      description: '',
      reminder: true
    }
  },

  onLoad() {
    this.setCurrentDate()
    this.loadCalendar()
  },

  onShow() {
    this.loadCalendar()
  },

  setCurrentDate() {
    const now = new Date()
    const year = now.getFullYear()
    const month = (now.getMonth() + 1).toString().padStart(2, '0')
    const day = now.getDate().toString().padStart(2, '0')
    const dateStr = `${year}-${month}-${day}`
    this.setData({
      currentDate: dateStr,
      selectedDate: dateStr
    })
  },

  loadCalendar() {
    const calendarList = wx.getStorageSync('calendar') || []
    this.setData({
      calendarList: calendarList
    })
  },

  onDateChange(e) {
    this.setData({
      selectedDate: e.detail.value
    })
  },

  addCalendar() {
    this.setData({
      showAddModal: true,
      newCalendar: {
        title: '',
        time: '',
        description: '',
        reminder: true
      }
    })
  },

  hideAddModal() {
    this.setData({
      showAddModal: false
    })
  },

  onInputChange(e) {
    const field = e.currentTarget.dataset.field
    this.setData({
      [`newCalendar.${field}`]: e.detail.value
    })
  },

  onReminderChange(e) {
    this.setData({
      'newCalendar.reminder': e.detail.value
    })
  },

  confirmAdd() {
    const { newCalendar, selectedDate } = this.data
    if (!newCalendar.title) {
      wx.showToast({
        title: '请输入日程标题',
        icon: 'none'
      })
      return
    }

    const calendarList = wx.getStorageSync('calendar') || []
    const calendar = {
      id: Date.now().toString(),
      ...newCalendar,
      date: selectedDate,
      createdAt: new Date().toISOString()
    }
    calendarList.push(calendar)
    wx.setStorageSync('calendar', calendarList)

    this.setData({
      showAddModal: false,
      calendarList: calendarList
    })

    wx.showToast({
      title: '添加成功',
      icon: 'success'
    })

    // 如果设置了提醒，发送到服务器
    if (newCalendar.reminder) {
      this.setReminder(calendar)
    }
  },

  setReminder(calendar) {
    wx.request({
      url: `${app.globalData.serverUrl}/api/calendar/reminder`,
      method: 'POST',
      data: calendar,
      success: (res) => {
        console.log('提醒设置成功', res)
      }
    })
  },

  deleteCalendar(e) {
    const calendarId = e.currentTarget.dataset.id
    wx.showModal({
      title: '确认删除',
      content: '确定要删除这个日程吗？',
      success: (res) => {
        if (res.confirm) {
          let calendarList = wx.getStorageSync('calendar') || []
          calendarList = calendarList.filter(c => c.id !== calendarId)
          wx.setStorageSync('calendar', calendarList)
          this.setData({ calendarList: calendarList })
          wx.showToast({
            title: '删除成功',
            icon: 'success'
          })
        }
      }
    })
  },

  onPullDownRefresh() {
    this.loadCalendar()
    wx.stopPullDownRefresh()
  }
})

// pages/settings/settings.js
const app = getApp()
const api = require('../../utils/api.js')

Page({
  data: {
    settings: {
      notifications: true,
      privacyMode: false,
      autoConnect: true,
      language: 'zh'
    },
    serverUrl: '',
    mqttUrl: '',
    deviceId: '',
    version: '1.0.0',
    loggedIn: false,
    userId: ''
  },

  onLoad() {
    this.loadSettings()
    this.loadConfig()
    this.setData({
      loggedIn: !!wx.getStorageSync('accessToken'),
      userId: wx.getStorageSync('userId') || ''
    })
  },

  async doLogin() {
    try {
      await api.login()
      this.setData({
        loggedIn: true,
        userId: wx.getStorageSync('userId') || ''
      })
      wx.showToast({ title: '登录成功', icon: 'success' })
    } catch (e) {
      wx.showToast({ title: '登录失败: ' + e.message, icon: 'none' })
    }
  },

  loadSettings() {
    const settings = wx.getStorageSync('settings') || {
      notifications: true,
      privacyMode: false,
      autoConnect: true,
      language: 'zh'
    }
    this.setData({ settings: settings })
  },

  loadConfig() {
    this.setData({
      serverUrl: app.globalData.serverUrl,
      mqttUrl: app.globalData.mqttUrl,
      deviceId: app.globalData.deviceId || '未设置'
    })
  },

  onSettingChange(e) {
    const field = e.currentTarget.dataset.field
    const value = e.detail.value
    const settings = this.data.settings
    settings[field] = value
    this.setData({ settings: settings })
    wx.setStorageSync('settings', settings)

    wx.showToast({
      title: '设置已保存',
      icon: 'success'
    })
  },

  onServerUrlChange(e) {
    this.setData({
      serverUrl: e.detail.value
    })
    app.globalData.serverUrl = e.detail.value
    wx.setStorageSync('serverUrl', e.detail.value)
  },

  onMqttUrlChange(e) {
    this.setData({
      mqttUrl: e.detail.value
    })
    app.globalData.mqttUrl = e.detail.value
    wx.setStorageSync('mqttUrl', e.detail.value)
  },

  clearData() {
    wx.showModal({
      title: '确认清除',
      content: '确定要清除所有本地数据吗？此操作不可恢复。',
      success: (res) => {
        if (res.confirm) {
          wx.clearStorageSync()
          this.loadSettings()
          wx.showToast({
            title: '数据已清除',
            icon: 'success'
          })
        }
      }
    })
  },

  exportData() {
    const data = {
      devices: wx.getStorageSync('devices') || [],
      calendar: wx.getStorageSync('calendar') || [],
      settings: wx.getStorageSync('settings') || {}
    }

